using System;
using System.Linq;
namespace CashflowChains.Domain {
 public static class TravelInsight {
  public static string Name(Piece p)=>p.Id=="home"||p.Id=="apartment"?"Residents":p.Label;
  public static string Resource(int kind)=>kind==0?"customers":kind==1?"stock":"power";
  public static string Recipe(Piece p)=>string.Join(" + ",Enumerable.Range(0,3).Where(k=>p.Need[k]>0).Select(k=>p.Need[k]+" "+Resource(k)));
  public static string Role(Piece p){if(p.SourceKind==0)return (p.Id.Contains("office")?"Workers":"Residents")+" make up to "+p.SourceRate+" shop visits per minute.";if(p.Id=="farm")return "Harvests 2 stock per minute. Shops use it to serve customers.";if(p.SourceKind>=0)return "Produces "+p.SourceRate+" "+Resource(p.SourceKind)+" per minute.";if(p.Credits>0)return Recipe(p)+" → $"+p.Credits+" per sale; up to "+p.Rate+" sales/min.";if(p.Rate>0)return p.Id=="warehouse"||p.Id=="logistics"||p.Id=="freight_yard"||p.Id=="tram"?"Receives and forwards "+Resource(RoadRouting.OutputKind(p))+"; faster outbound journeys.":Recipe(p)+" → "+string.Join(" + ",Enumerable.Range(0,3).Where(k=>p.Make[k]>0).Select(k=>p.Make[k]+" "+Resource(k)))+".";return p.Id=="bank"?"Raises one next-door shop’s sales by 25%; banks never stack.":p.Id=="park"?"Next-door homes attract 15% more visits; next-door cafés earn 5% more.":p.Hint;}
  public static string Describe(Board board,RoundResult result,int id){var n=board.Nodes.Find(x=>x.Id==id);if(n==null)return "Choose a building to inspect its job and travel times.";var p=Pieces.Get(n.Kind);var trips=result.Events.Where(e=>e.Reason=="shipment"&&e.Source==id).ToArray();if(RoadRouting.OutputKind(p)>=0){var first=trips.FirstOrDefault();if(first==null)return Role(p)+" Choose a compatible destination with room.";var target=board.Nodes.Find(x=>x.Id==first.Target);return Name(p)+" → "+Pieces.Get(target.Kind).Label+": "+first.TravelSteps+" min travel. "+(p.Id=="farm"?"Harvests stock; shops turn it into sales.":"Shorter trips leave more time to trade.");}var sales=result.Events.Where(e=>e.Reason=="sale"&&e.Source==id).ToArray();if(sales.Length>0)return p.Label+": "+sales.Sum(e=>e.Count)+" sales; first at minute "+sales[0].Beat+". Needs "+Recipe(p)+" per sale.";if(p.Credits>0){var missing=Enumerable.Range(0,3).Where(k=>p.Need[k]>0&&(k==1?n.InitialGoods:k==2?n.InitialEnergy:0)==0&&!result.Events.Any(e=>e.Reason=="arrival"&&e.Target==id&&e.Kind==k)).Select(Resource);return p.Label+": "+string.Join(" + ",missing)+" did not arrive before closing. Check sources and journey times.";}return Role(p);}
 }
}
